from __future__ import annotations

import json
from typing import Any, Callable

from fastapi import Depends, HTTPException, Request, status

from backend.auth.contracts import ActorContext
from backend.auth.implementation import (
    AuthSessionService,
    AuthenticationRequired,
    AuthorizationDenied,
    ClaimsNormalizationError,
)


def build_current_actor_dependency(
    *,
    auth_service: AuthSessionService | None = None,
) -> Callable[[Request], ActorContext]:
    service = auth_service or AuthSessionService()

    def current_actor(request: Request) -> ActorContext:
        try:
            claims, source = _extract_claims(request)
        except HTTPException as exc:
            service.log_access_decision(
                "auth.authentication_rejected",
                headers=dict(request.headers),
                claims={},
                actor_id=None,
                auth_source=None,
            )
            raise exc

        if source is None:
            service.log_access_decision(
                "auth.anonymous_rejected",
                headers=dict(request.headers),
                claims={},
                actor_id=None,
                auth_source=None,
            )
            raise HTTPException(
                status_code=status.HTTP_401_UNAUTHORIZED,
                detail="Authentication required",
            )

        try:
            actor = service.normalize_claims(claims, source)
        except (AuthenticationRequired, ClaimsNormalizationError) as exc:
            service.log_access_decision(
                "auth.authentication_rejected",
                headers=dict(request.headers),
                claims=claims,
                actor_id=None,
                auth_source=source,
            )
            raise HTTPException(
                status_code=status.HTTP_401_UNAUTHORIZED,
                detail="Authentication required",
            ) from exc

        request.state.actor = actor
        return actor

    return current_actor


def build_permission_dependency(
    required_permission: str,
    *,
    auth_service: AuthSessionService | None = None,
    actor_dependency: Callable[..., ActorContext] | None = None,
) -> Callable[..., ActorContext]:
    service = auth_service or AuthSessionService()
    current_actor = actor_dependency or build_current_actor_dependency(
        auth_service=service,
    )

    def require_permission(
        request: Request,
        actor: ActorContext = Depends(current_actor),
    ) -> ActorContext:
        try:
            service.require_permission(actor, required_permission)
        except AuthorizationDenied as exc:
            service.log_access_decision(
                "auth.authorization_denied",
                headers=dict(request.headers),
                claims=getattr(request.state, "auth_claims", {}),
                actor_id=exc.actor_id,
                auth_source=actor.idp_type,
            )
            raise HTTPException(
                status_code=status.HTTP_403_FORBIDDEN,
                detail="Forbidden",
            ) from exc

        return actor

    return require_permission


def _extract_claims(
    request: Request,
) -> tuple[dict[str, Any], str | None]:
    oidc_claims_header = request.headers.get("x-oidc-claims")
    saml_claims_header = request.headers.get("x-saml-claims")

    if oidc_claims_header and saml_claims_header:
        request.state.auth_claims = {}
        request.state.auth_source = None
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Authentication required",
        )

    if oidc_claims_header:
        claims = _parse_claims_header(oidc_claims_header)
        request.state.auth_claims = claims
        request.state.auth_source = "oidc"
        return claims, "oidc"

    if saml_claims_header:
        claims = _parse_claims_header(saml_claims_header)
        request.state.auth_claims = claims
        request.state.auth_source = "saml"
        return claims, "saml"

    request.state.auth_claims = {}
    request.state.auth_source = None
    return {}, None


def _parse_claims_header(raw_value: str) -> dict[str, Any]:
    try:
        parsed = json.loads(raw_value)
    except json.JSONDecodeError as exc:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Authentication required",
        ) from exc

    if not isinstance(parsed, dict):
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Authentication required",
        )

    return {str(key): value for key, value in parsed.items()}
