from fastapi import APIRouter, Depends

from backend.shared.authz.dependencies import build_current_actor_dependency

from .contracts import ActorContext
from .implementation import AuthSessionService


def build_auth_router(
    *,
    auth_service: AuthSessionService | None = None,
) -> APIRouter:
    service = auth_service or AuthSessionService()
    current_actor = build_current_actor_dependency(auth_service=service)
    router = APIRouter()

    @router.get("/auth/me", response_model=ActorContext)
    def get_auth_me(actor: ActorContext = Depends(current_actor)) -> ActorContext:
        return actor

    return router
