class RecordingWritePort:
    def __init__(self) -> None:
        self.calls: list[dict[str, object]] = []

    def write(
        self,
        command: ProtectedMutationRequest,
        actor: ActorContext,
    ) -> dict[str, object]:
        record = {
            "document_id": command.document_id,
            "payload": dict(command.payload),
            "actor_id": actor.id,
            "username": actor.username,
        }
        self.calls.append(record)
        return {
            "document_id": command.document_id,
            "persisted_by": actor.id,
        }


class RecordingAuditPort:
    def __init__(self) -> None:
        self.events: list[dict[str, object]] = []

    def record(
        self,
        event_type: str,
        actor: ActorContext,
        detail: dict[str, object],
    ) -> None:
        self.events.append(
            {
                "event_type": event_type,
                "actor_id": actor.id,
                "detail": detail,
            },
        )


class RecordingLogger:
    def __init__(self) -> None:
        self.records: list[dict[str, object]] = []

    def log(
        self,
        level: int,
        message: str,
        *,
        extra: dict[str, object] | None = None,
    ) -> None:
        self.records.append(
            {
                "level": level,
                "message": message,
                "extra": extra or {},
            },
        )


